import styled from '@emotion/styled';
import { ExpandMore } from '@mui/icons-material';
import {
  Typography,
  Box,
  Button,
  Accordion,
  AccordionSummary,
  AccordionDetails,
} from '@mui/material';
import React, { useContext } from 'react';
import { TheAppContext } from '../../../provider/AppContext';

import MenuNest from './MobileNest';
import { menuItems } from '../../../data/menu/menu';
const Multiplier = 50;
const Styled__Wrap = styled.div`
  height: calc(100vh - ${Multiplier}px);
  width: calc(100vw - ${Multiplier}px);
  background-color: rgba(0, 0, 0, 0);
  color: white;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  /* padding: ${Multiplier / 2}px; */
  transform: translate(${Multiplier / 2}px, ${Multiplier / 2}px);
  margin-bottom: ${Multiplier}px;
`;
const MobileMenu = () => {
  const { setMenuOpen } = useContext(TheAppContext);

  const [expanded, setExpanded] = React.useState<string | false>(false);

  const handleChange =
    (panel: string) => (event: React.SyntheticEvent, isExpanded: boolean) => {
      setExpanded(isExpanded ? panel : false);
    };

  return (
    <Styled__Wrap>
      <Box>
        {menuItems.map((i) => (
          <Accordion
            expanded={expanded === i.id}
            onChange={handleChange(`${i.id}`)}
            key={i.id}
            sx={{ backgroundColor: 'black' }}
            // onTouchEnd={() => setExpanded(`${i.id}`)}
          >
            <AccordionSummary
              expandIcon={<ExpandMore />}
              aria-controls="panel1bh-content"
              id="panel1bh-header"
            >
              <Typography variant="h5">{i.displayName}</Typography>
            </AccordionSummary>
            <AccordionDetails>
              {i.items.map((item) => (
                <MenuNest
                  key={item.id}
                  customClasses={item.customClasses}
                  displayName={item.displayName}
                  subItems={item.items}
                />
              ))}
            </AccordionDetails>
          </Accordion>
        ))}
        <Button
          fullWidth
          sx={{ marginTop: '40px' }}
          variant="contained"
          onClick={() => setMenuOpen(false)}
        >
          Close
        </Button>
      </Box>
    </Styled__Wrap>
  );
};

export default MobileMenu;
