import React, { useContext, useState } from 'react';
import { TheAppContext } from 'provider/AppContext';
import * as styles from './contact.module.css';
import Success from './Success';
import Submitting from './Submitting';
import Error from './Error';

import { Button, Typography } from '@mui/material';
import { Email, GitHub, LinkedIn } from '@mui/icons-material';
const initInputs = [
  {
    displayName: 'Name',
    id: 'name',
    content: '',
    required: true,
    type: 'text',
  },
  {
    displayName: 'Email',
    id: 'email',
    content: '',
    required: true,
    type: 'text',
  },
  {
    displayName: 'Subject',
    id: 'subject',
    content: '',
    required: true,
    type: 'text',
  },
  {
    displayName: 'Message',
    id: 'message',
    content: '',
    required: true,
    type: 'textarea',
  },
];
const Contact = () => {
  const { setBoxShowing } = useContext(TheAppContext);
  const [form, setForm] = useState<any>({
    status: 'filling',
    inputs: initInputs,
    message: 'Contact Me',
    errors: [],
  });

  const handleChange = (e) => {
    const name = e.target.name;
    const inputs = [...form.inputs];
    let input = inputs.find((i) => i.id === name);
    input.content = e.target.value;
    setForm((prev) => ({ ...prev, inputs }));
  };

  const handleSubmit = async () => {
    setForm((prev) => ({
      ...prev,
      status: 'submitting',
      message: 'Hang On...',
    }));
    let formJson: Record<string, string> = {};
    form.inputs.forEach((i: any) => {
      if (i.content === '') {
        setForm((prev) => ({
          ...prev,
          status: 'filling',
          errors: ['Please fill out all fields!'],
        }));
        throw 'An error occured';
      }
      formJson[i.id] = i.content;
    });

    return await fetch('http://localhost:1234', {
      mode: 'no-cors',
      headers: {
        'content-type': 'application/json',
      },
      method: 'POST',
      body: JSON.stringify(formJson),
    })
      // .then((res) => res.json())
      .then((result) => {
        setForm((prev) => ({
          ...prev,
          status: 'complete',
          message: 'Thanks!',
        }));
      })
      .catch((err) => {
        console.log({ err });
        setForm((prev) => ({
          ...prev,
          status: 'filling',
          message: 'Try Again...',
        }));
      });
  };

  const styleArray = [
    styles.contact,
    'bg--3',
    form.status === 'complete' ? styles.complete : null,
    form.status === 'submitting' ? styles.submitting : null,
  ];

  const handleClose = () => {
    setBoxShowing({ visible: false, component: null });
  };
  return (
    <div className={styleArray.join(' ')}>
      <Typography variant="h5" sx={{ color: 'black' }}>
        {form.message}
      </Typography>
      {form.status === 'submitting' && <Submitting />}
      {form.status === 'complete' && <Success handleClose={handleClose} />}
      {form.status === 'filling' && (
        <>
          {form.errors.length > 0 ? <Error errors={form.errors} /> : ''}
          <div className={styles.inputArea}>
            {form.inputs.map((i, index) => (
              <div key={`${i.id}--${index}`} className={styles.input}>
                <label htmlFor={i.id}>{i.displayName}</label>
                {i.type === 'text' ? (
                  <input
                    name={i.id}
                    onChange={handleChange}
                    type={i.type || 'text'}
                    placeholder={i.displayName}
                  />
                ) : (
                  <textarea
                    name={i.id}
                    onChange={handleChange}
                    placeholder={i.displayName}
                  ></textarea>
                )}
              </div>
            ))}
          </div>
          <Button onClick={handleSubmit} variant="contained">
            {form.errors.length > 0 ? 'Try Again...' : 'Contact'}
          </Button>
        </>
      )}
      <div className={styles.reachMe}>
        <div className={styles.ital}> You can also reach me here: </div>
        <div className={styles.reachIcons}>
          <a
            href={'https://www.linkedin.com/in/albertksigman26/'}
            target="_blank"
            rel="prefetch"
          >
            <LinkedIn />
          </a>
          <a
            href={'https://github.com/nightingalemedia'}
            target="_blank"
            rel="prefetch"
          >
            <GitHub />
          </a>
          <a href="mailto:alsigman@gmail.com" target="_blank" rel="prefetch">
            <Email />
          </a>
        </div>
      </div>
    </div>
  );
};

export default Contact;
